import base64
import os

def save_base64_file_from_content_block(content_block,save_dir):
    return save_base64_file(
        base64_data=content_block["data"],
        mime_type=content_block["mimeType"],
        filename=content_block["metadata"]["filename"],
        save_dir=save_dir
    )

def save_base64_file(
        base64_data: str,
        mime_type: str,
        filename: str,
        save_dir: str
):
    """
    将 base64 数据保存为文件

    Args:
        base64_data: base64 编码的字符串
        mime_type: 文件类型，如 'image/jpeg', 'application/pdf'
        filename: 原始文件名
        save_dir: 保存目录

    Returns:
        Dict: 包含文件信息的字典
    """

    file_path = os.path.join(save_dir, filename)
    # 解码 base64 数据
    file_data = base64.b64decode(base64_data)

    # 保存文件
    with open(file_path, 'wb') as f:
        f.write(file_data)

    return {
        "success": True,
        "file_path": str(file_path),
        "filename": filename,
        "mime_type": mime_type,
        "size": len(file_data)
    }



# 使用示例
if __name__ == "__main__":
    # 假设从前端接收到的数据
    content_block = {'type': 'file', 'mimeType': '', 'data': '', 'metadata': {'filename': 'agent历史与概念.md', 'size': 8238, 'lastModified': 1757389979338}}

    result = save_base64_file(
        base64_data=content_block["data"],
        mime_type=content_block["mimeType"],
        filename=content_block["metadata"]["filename"],
        save_dir=r'D://agent_files'
    )

    print(result)